let language=new URLSearchParams(location.search).get('lang')||localStorage.getItem('meguru-language')||'ja';if(!['ja','en'].includes(language))language='ja';
const en=()=>language==='en',tr=(ja,english)=>en()?english:ja;
const englishNames={1:'Haruka Tanaka',2:'Makoto Sato',3:'Yuko Suzuki',4:'Akira Yamamoto'};
const displayName=u=>en()?(englishNames[u.id]||u.name):u.name;
const category=t=>en()?({'すべて':'All','暮らし':'Home','衣類・バッグ':'Clothing & bags','本・あそび':'Books & play','防災用品':'Emergency supplies'}[t]||t):t;
function localTime(t){return new Date(t).toLocaleTimeString(en()?'en-GB':'ja-JP',{hour:'2-digit',minute:'2-digit'})}
due=p=>localTime(p.reservation.until);
avatar=function(u){return u.consent&&u.face?`<img class="avatar" src="${esc(u.face)}" alt="${esc(displayName(u))}${tr('さんの顔写真（架空）',' (fictional resident)')}">`:`<span class="avatar" aria-label="${tr('顔写真非公開','Photo not shared')}">◯</span>`};
seller=u=>`${avatar(u)}<span>${esc(displayName(u))}${tr(' さん','')}</span>`;
market=function(){expire();$('#main').innerHTML=`<div class="resident-top"><div class="filters">${['すべて',...tags].map(t=>`<button class="pill ${filter===t?'active':''}" data-filter="${t}">${category(t)}</button>`).join('')}</div><aside class="point-wallet" aria-label="${tr('現在のポイント残高','Current points balance')}"><div><span class="wallet-label">${tr('あなたのポイント','YOUR POINTS')}</span><span class="wallet-owner">${esc(displayName(me()))}${tr(' さん','')}</span></div><div class="wallet-value"><strong>${me().points.toLocaleString(en()?'en-GB':'ja-JP')}</strong><span>pt</span></div></aside></div><div class="grid" id="products"></div><p class="muted" style="margin-top:28px">${tr('交換・ポイントの調整は現地のスタッフ受付で。','Exchanges and point adjustments are handled by staff at the venue.')}</p>`;document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;market()});cards()};
cards=function(){let ps=state.products.filter(p=>filter==='すべて'||p.category===filter);$('#products').innerHTML=ps.map(p=>`<button class="card" data-item="${p.id}" aria-label="${tr('商品を見る','View item')} #${p.id}"><div class="photo"><img src="${esc(p.image)}" alt="${esc(category(p.category))} #${p.id}" loading="lazy"><span class="tag">${esc(category(p.category))}</span>${p.sold?`<div class="sold">${tr('交換済み','Collected')}</div>`:active(p)?`<span class="reservebadge">${p.reservation.by===uid?tr('あなたが予約中','Reserved by you'):tr('予約中','Reserved')} · ${tr('あと','')}${left(p)}${tr('分',' min left')}</span>`:''}</div><div class="cardbody"><div class="seller">${seller(user(p.seller))}</div></div></button>`).join('')||`<p class="muted">${tr('まだありません。','No items here yet.')}</p>`;document.querySelectorAll('[data-item]').forEach(b=>b.onclick=()=>detail(+b.dataset.item))};
detail=function(id){expire();opened=id;const p=state.products.find(p=>p.id===id);$('#detail').innerHTML=`<button class="close" aria-label="${tr('閉じる','Close')}">×</button><img class="modalphoto" src="${esc(p.image)}" alt="${tr('商品','Item')} #${id}"><div class="modalbody"><span class="muted">${esc(category(p.category))} · #${id}</span><div class="seller">${seller(user(p.seller))}</div><div style="margin-top:24px">${p.sold?`<p>${tr('交換済みです','This item has been collected.')}</p>`:active(p)?p.reservation.by===uid?`<p><b>${tr(due(p)+' までにスタッフ受付へ','Go to the staff desk by '+due(p))}</b><br><span class="muted">${tr('あと'+left(p)+'分。期限を過ぎると自動解除されます。',left(p)+' minutes left. Your reservation expires automatically.')}</span></p><button class="secondary" id="cancel">${tr('予約を取り消す','Cancel reservation')}</button>`:`<p>${tr('ほかの方が予約中です','Reserved by another resident.')}</p>`:p.seller===uid?`<p class="muted">${tr('あなたの出品です','This is your item.')}</p>`:`<button class="primary" id="reserve">${tr('30分以内に取りに行く',"I'll collect within 30 minutes")}</button><p class="muted">${tr('30分間取り置きします。交換とポイントの調整は現地で。','We will hold this item for 30 minutes. Staff handle the exchange and points at the venue.')}</p>`}</div></div>`;$('#detail .close').onclick=()=>$('#detail').close();if($('#reserve'))$('#reserve').onclick=()=>{reserve(id);detail(id);market()};if($('#cancel'))$('#cancel').onclick=()=>{if(active(p)&&p.reservation.by===uid){delete p.reservation;save()}detail(id);market()};if(!$('#detail').open)$('#detail').showModal()};
function notification(n){if(!en())return n.text;if(n.item){let buyer=user(n.buyer);return n.notify&&buyer?`${displayName(buyer)} from room ${buyer.room} collected item #${n.item}.`:`Item #${n.item} was collected at the venue.`}let match=n.text.match(/^(.*?)号室の(.*?)さんが/);return match?`A resident from room ${match[1]} collected your item.`:'Your item was exchanged at the venue.'}
notices=function(){let ns=state.notices.filter(n=>n.to===uid);$('#main').innerHTML=`<h2>${tr('お知らせ','Notifications')}</h2><div class="panel">${ns.map(n=>`<div class="notice"><small class="muted">${esc(n.time)}</small><p>${esc(notification(n))}</p></div>`).join('')||`<p class="muted">${tr('まだありません。','No notifications yet.')}</p>`}</div>`;ns.forEach(n=>n.read=true);save();$('#badge').textContent=''};
const baseRender=render;
render=function(){const residentEnglish=en()&&page!=='staff';document.documentElement.lang=residentEnglish?'en':'ja';document.title=tr('めぐる団地 — 防災フェスのフリマ','Meguru Danchi — Community Market');$('.brand').textContent=tr('◒ めぐる団地','◒ Meguru Danchi');document.querySelector('[data-page="market"]').textContent=tr('商品をさがす','Browse');document.querySelector('[data-page="notices"]').innerHTML=`${tr('お知らせ','Notifications')} <span id="badge"></span>`;document.querySelector('[data-page="staff"]').textContent='スタッフ管理';$('#resident-label').textContent=tr('体験する住民','Demo resident');$('#user').innerHTML=state.users.map(u=>`<option value="${u.id}" ${u.id===uid?'selected':''}>${esc(displayName(u))}${tr(' さん','')}</option>`).join('');$('.demo').textContent=tr('デモ · 架空の人物・商品／予約はこのブラウザー内のみ','Demo · Fictional people and items / Reservations are stored in this browser only');$('#footer-copy').textContent=tr('めぐる団地　 /　ものをつなぐ。顔がつながる。','Meguru Danchi / Shared things. Familiar faces.');$('#reset').textContent=tr('デモを初期状態に戻す','Reset demo');$('#language').value=language;baseRender()};
$('#language').onchange=e=>{language=e.target.value;localStorage.setItem('meguru-language',language);let url=new URL(location.href);url.searchParams.set('lang',language);history.replaceState(null,'',url);render();if(opened)detail(opened)};
$('#reset').onclick=()=>{if(confirm(tr('デモを初期状態に戻しますか？','Reset all demo data?'))){state=initial();applyProductPhotos();save();render();toast(tr('デモを初期状態に戻しました','Demo reset'))}};
function applyProductPhotos(){state.products.forEach(p=>{if(p.id>=1&&p.id<=6&&/^https:\/\/images\.unsplash\.com\//.test(p.image)){p.image=`assets/item-${p.id}.png`}})}applyProductPhotos();save();render();
